"Make admin":["Beheerder maken", "جعله مسؤولًا"],
"Turn off 2FA":["2FA uitzetten", "إيقاف التحقق بخطوتين"],
"Turn off two-factor sign-in for {name}? Use this when they lost their phone; they can turn it on again.":["Tweestapsaanmelding uitzetten voor {name}? Gebruik dit als die persoon de telefoon kwijt is; het kan daarna weer aangezet worden.", "إيقاف تسجيل الدخول بخطوتين لـ {name}؟ استخدم هذا عند فقدان هاتفه؛ ويمكنه تفعيله مجددًا."],
"Two-factor sign-in is off for {name}.":["Tweestapsaanmelding staat uit voor {name}.", "تسجيل الدخول بخطوتين متوقف لـ {name}."],
"Remove":["Verwijderen", "إزالة"],
"Remove {name}?\nTheir {n} links, groups and pictures are deleted too. This cannot be undone.":["{name} verwijderen?\nDe {n} links, groepen en afbeeldingen van deze persoon worden ook verwijderd. Dit kan niet ongedaan worden gemaakt.", "إزالة {name}؟\nستُحذف أيضًا روابطه ({n}) ومجموعاته وصوره. لا يمكن التراجع عن ذلك."],
"{name} removed.":["{name} verwijderd.", "أُزيل {name}."],
"{name} can now sign in.":["{name} kan zich nu aanmelden.", "يمكن لـ {name} الآن تسجيل الدخول."],
"The backup could not be made ({code}).":["De back-up kon niet worden gemaakt ({code}).", "تعذّر إنشاء النسخة الاحتياطية ({code})."],
"Encrypted backup downloaded. Keep the password: without it the file cannot be opened.":["Versleutelde back-up gedownload. Bewaar het wachtwoord: zonder kan het bestand niet worden geopend.", "نُزّلت نسخة احتياطية مشفّرة. احتفظ بكلمة المرور: فبدونها لا يمكن فتح الملف."],
"Backup downloaded (not encrypted).":["Back-up gedownload (niet versleuteld).", "نُزّلت النسخة الاحتياطية (غير مشفّرة)."],
"Choose a backup file first.":["Kies eerst een back-upbestand.", "اختر ملف نسخة احتياطية أولًا."],
"Replace ALL your current links and groups with the contents of this backup?":["AL je huidige links en groepen vervangen door de inhoud van deze back-up?", "استبدال كل روابطك ومجموعاتك الحالية بمحتوى هذه النسخة الاحتياطية؟"],
"Restored {links} links in {groups} groups.":["{links} links in {groups} groepen teruggezet.", "استُعيدت {links} روابط في {groups} مجموعات."],
"{n} links were not added because you already have them.":["{n} links zijn niet toegevoegd omdat je ze al hebt.", "لم تُضف {n} روابط لأنها موجودة لديك بالفعل."],
"{n} of them have exactly the same address.":["{n} daarvan hebben precies hetzelfde adres.", "{n} منها لها العنوان نفسه تمامًا."],
"Download them to keep a copy, keep some as separate links, or discard them.":["Download ze om een kopie te houden, bewaar er een paar als aparte links, of gooi ze weg.", "نزّلها للاحتفاظ بنسخة، أو احتفظ ببعضها كروابط منفصلة، أو تجاهلها."],
"Identical address: already saved":["Hetzelfde adres: al opgeslagen", "عنوان مطابق: محفوظ بالفعل"],
"Keep as a separate link":["Als aparte link bewaren", "الاحتفاظ به كرابط منفصل"],
"the same page appears earlier in this import":["dezelfde pagina staat eerder in deze import", "الصفحة نفسها تظهر في موضع سابق من هذا الاستيراد"],
"identical address":["hetzelfde adres", "عنوان مطابق"],
"Kept {n} as separate links; the rest were discarded.":["{n} als aparte links bewaard; de rest is weggegooid.", "احتُفظ بـ {n} كروابط منفصلة؛ وتم تجاهل الباقي."],
"Duplicates discarded.":["Dubbele links weggegooid.", "تم تجاهل التكرارات."],
"Duplicates ({n})":["Dubbele links ({n})", "التكرارات ({n})"],
